{
  "index_test": "whole-animal-in-vivo",
  "index_test_evidence": "The ZeGlobalTox assay, an innovative experimental procedure that addresses organ-specific toxicity of different drugs on zebrafish larvae (up to 5 dpf). Thus, the proposed approach allows the independent analysis of cardio-, neuro-, and hepatotoxicity effects in the same animal ( Figure 1 A,B), as a proxy to predict their possible impact in human organs.",
  "decision": "include",
  "reason": "The study uses whole zebrafish larvae (in vivo) to predict human organ toxicity and reports quantitative measures of agreement (specificity 89%, sensitivity 68%, and accuracy 78%)."
}
